def normalize(name):
    if '端口' in name:
        return '端口最小化'
    if '密码' in name:
        return '默认密码已改'
    if '防火墙' in name:
        return '防火墙已开'
    if '更新' in name:
        return '系统更新已装'
    return name

unfixed = []
for i in range(4):
    line = input()
    name, status = line.split(',')
    if status == '未做':
        unfixed.append(normalize(name))

